  if (execFileSync('git', ['branch', '--show-current'], { cwd: repo, encoding: 'utf8' }).trim() !== 'feature/phase-9a-learning-mode') throw Error('Wrong branch')
  const runId = `${new Date().toISOString().replace(/[:.]/g, '-')}-R6-staged`
