    'out/exercise-shutdown-9d-common', 'spikes/exercise-runtime-9d0',
    'spikes/exercise-shutdown-9d-common/evidence', 'node_modules/node-pty/prebuilds', 'node_modules/node-pty/build/Release']) walk(dir)
  return hashes
}
